RETURNS BOOLEAN CALLED ON NULL INPUT IMMUTABLE PARALLEL SAFE AS $$
DECLARE
  res bool;
  tag_0 JSONB;
  fun_0 TEXT;
BEGIN
  -- MCP - Model Context Protocol
  -- .
  res := JSONB_TYPEOF(val) = 'object';
  IF res THEN
    IF val ? 'method' THEN
      tag_0 := val -> 'method';
      fun_0 := jm_cmap_get('_jm_map_0', tag_0);
      res := fun_0 IS NOT NULL AND jm_call(fun_0, val, NULL, NULL);
    ELSE
      res := FALSE;
    END IF;
  END IF;
  RETURN res OR json_model_6(val, NULL, NULL) OR json_model_9(val, NULL, NULL) OR json_model_11(val, NULL, NULL);
END;
$$ LANGUAGE PLpgSQL;

CREATE OR REPLACE FUNCTION check_model_map(name TEXT)
RETURNS TEXT STRICT IMMUTABLE PARALLEL SAFE AS $$
DECLARE
  map JSONB := JSONB '{"":"json_model_1","Object":"json_model_2","ProtocolVersion":"json_model_3","Tool":"json_model_4","InitializeRequest":"json_model_5","InitializeResponse":"json_model_6","Notification":"json_model_7","ToolsListRequest":"json_model_8","ToolsListResponse":"json_model_9","ToolCallRequest":"json_model_10","ToolCallResponse":"json_model_11"}';
BEGIN
  RETURN map->>name;
END;
$$ LANGUAGE plpgsql;

--
-- constant maps initialization
--
TRUNCATE jm_constant_maps;
INSERT INTO jm_constant_maps(mapname, tagval, value) VALUES
  ('_jm_map_0', JSONB '"initialize"', 'json_model_5'),
  ('_jm_map_0', JSONB '"notifications/initialized"', 'json_model_7'),
  ('_jm_map_0', JSONB '"tools/list"', 'json_model_8'),
  ('_jm_map_0', JSONB '"tools/call"', 'json_model_10')
;

--
-- JSON Model checking entry point
--
-- TODO INOUT rep?
CREATE OR REPLACE FUNCTION check_model(val JSONB, name TEXT, rep jm_report_entry[])
RETURNS BOOLEAN CALLED ON NULL INPUT IMMUTABLE PARALLEL SAFE AS $$
DECLARE
  fun TEXT;
BEGIN
  fun := check_model_map(name);
  IF fun IS NULL THEN
    RAISE EXCEPTION 'model for % not found', name;
  END IF;
  RETURN jm_call(fun, val, NULL, rep);
END;
$$ LANGUAGE plpgsql;
